public static server GUPPricingAttributeValueTmp buildPricingAttributeValueTmp(RecId _pricingRuleRecId)
{
    GUPPricingAttributeValueTmp pricingAttributeValue;
    GUPPricingRuleCondition ruleCond;
    GUPPricingAttributeLink link;

    delete_from pricingAttributeValue;
    while select ruleCond
        where ruleCond.RuleId == _pricingRuleRecId
        join Priority from link
        order by Priority desc
        where ruleCond.ConditionAttribute == link.RecId
    {
        pricingAttributeValue.AttributeName = ruleCond.pricingAttribute().getName();
        pricingAttributeValue.AttributeValue = GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                                                                            ruleCond.pricingAttribute().getName(),
                                                                            ruleCond.ConditionValue,
                                                                            ruleCond.priceAttributeLink());
        pricingAttributeValue.Priority = link.Priority;
        pricingAttributeValue.insert();
    }

    return pricingAttributeValue;
}
